mapper.select:
/* selectMasterMdCpAdminApprovalObjctList */ SELECT ROWNUM NUM, A.USER_ID, F_GET_MASKING_RETURN(A.USER_ID, 'NAME') AS USER_ID_MASK, A.USER_NAME, F_GET_MASKING_RETURN(A.USER_NAME, 'NAME') AS USER_NAME_MASK, A.COM_NAME, A.DEPT_NAME, A.TEL, F_GET_MASKING_RETURN(A.TEL, 'PHONE') AS TEL_MASK, A.COM_STATUS_TEXT, A.USER_TYPE_TEXT, A.CHANGE_USER_TYPE_TEXT, A.USER_TYPE, A.CHANGE_USER_TYPE, A.USER_STATUS, A.COM_STATUS, A.COM_CODE, A.BUSINESS_COND, A.DEPT FROM ( SELECT L.USER_ID USER_ID, L.USER_NAME_LOC USER_NAME, C.COM_NAME_LOC COM_NAME, (SELECT TEXT1 FROM ICOMCOD2 WHERE TYPE='C001' AND COMPANY_CODE = L.COM_CODE AND CODE = L.DEPARTMENT ) AS DEPT_NAME, L.PHONE_NUMBER TEL, DECODE(C.STATUS,'C','승인','R','승인','S','미승인','B','업체반려') AS COM_STATUS_TEXT, DECODE(L.USER_TYPE,'A','Admin사용자','U','일반사용자') AS USER_TYPE_TEXT, DECODE(L.CHANGE_USER_TYPE,'A','Admin사용자','U','일반사용자') AS CHANGE_USER_TYPE_TEXT, L.USER_TYPE USER_TYPE, L.CHANGE_USER_TYPE CHANGE_USER_TYPE, L.STATUS USER_STATUS, C.STATUS COM_STATUS, L.COM_CODE COM_CODE, C.BUSINESS_COND , L.DEPARTMENT DEPT FROM ICOMLUSR L, ICOMCMPY C WHERE L.COM_CODE = C.COM_CODE AND ( (L.STATUS ='S' AND L.USER_TYPE='A') OR (L.STATUS ='R' AND L.USER_TYPE != L.CHANGE_USER_TYPE AND L.CHANGE_USER_TYPE = 'A' AND L.COM_CODE != 'KRKORE0001' ) ) AND C.STATUS IN ( 'C' ,'R')
AND L.USER_ID LIKE UPPER(#{st_search_user_id})||'%'
AND L.USER_NAME_LOC LIKE '%'||#{st_search_user_name}||'%'
AND C.COM_NAME_LOC LIKE '%'||#{st_search_com_name}||'%'
AND L.USER_TYPE = #{st_search_user_type}
ORDER BY L.REG_DATE DESC ) A

mapper.update:

UPDATE ICOMLUSR
SET
	STATUS		= #{st_status},



	USER_TYPE			= CHANGE_USER_TYPE,
	ROLE					= DECODE(CHANGE_USER_TYPE,'U','U+','A+'),
	CONFIRM_DATE		= TO_CHAR(SYSDATE,'YYYYMMDD'),
	CONFIRM_USER_ID	= #{st_user_id}




	REJECT_REASON	= #{st_reject_reason}




WHERE USER_ID = #{USER_ID}

