/*selectLogisRateMng_agentPop*/
SELECT COUNT(1) AS CNT
FROM LOGIS_RATE_MNG
WHERE 1=1
AND AGENT = #{com_code}

mapper.update:
/*insertLogisRateMng_agentPop */ MERGE INTO LOGIS_RATE_MNG A USING ( SELECT #{com_code} AS AGENT FROM DUAL ) B ON ( 1=1 AND A.AGENT = B.AGENT AND A.BUYER = 'ALL' ) WHEN MATCHED THEN UPDATE SET A.AGENT_IRS_NO = #{st_irs_no1} || '-' || #{st_irs_no2} || '-' || #{st_irs_no3} ,A.LOGIS_RATE = #{st_lgstrate} ,A.START_DATE = TO_CHAR(SYSDATE, 'YYYYMMDD') ,A.END_DATE = #{st_lgst_end_date} ,A.ADD_DATE = SYSDATE ,A.ADD_USER_ID = #{st_user_id} ,A.ADD_USER_NAME = (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = #{st_user_id}) ,A.CHANGE_DATE = SYSDATE ,A.CHANGE_USER_ID = #{st_user_id} ,A.CHANGE_USER_NAME = (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = #{st_user_id}) ,A.REMARK = #{st_lgstrate_remark}
WHEN NOT MATCHED THEN INSERT ( AGENT, BUYER, STATUS, AGENT_IRS_NO, BUYER_IRS_NO, LOGIS_RATE, AGENT_USER_NAME, START_DATE, END_DATE, ADD_DATE, ADD_USER_ID, ADD_USER_NAME, CHANGE_DATE, CHANGE_USER_ID, CHANGE_USER_NAME, REMARK, KEP_USER_NAME
) VALUES ( #{com_code}, 'ALL', 'C', #{st_irs_no1} || '-' || #{st_irs_no2} || '-' || #{st_irs_no3}, NULL, #{st_lgstrate}, (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE COM_CODE = #{com_code} AND ROWNUM = 1), TO_CHAR(SYSDATE, 'YYYYMMDD'), #{st_lgst_end_date}, SYSDATE, #{st_user_id}, (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = #{st_user_id}), SYSDATE, #{st_user_id}, (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = #{st_user_id}), #{st_lgstrate_remark}, NVL((SELECT TEXT4 FROM ICOMCOD3 WHERE TYPE ='CMSM' AND CODE2 = '1' AND CODE1 = (SELECT SG_ID FROM SUPLINFO2 WHERE SUPPLIER = #{com_code} AND SG_ID IS NOT NULL)),'') )
